func processAll(ctx context.Context, items []Item, out chan<- Result) error {
    for _, it := range items {
        if err := ctx.Err(); err != nil {
            return err                     // отменили — выходим
        }
        r := process(it)
        select {
        case out <- r:
        case <-ctx.Done():
            return ctx.Err()
        }
    }
    return nil
}

